using System.Security.Cryptography;
using System.Text;
using Renci.SshNet;
using Renci.SshNet.Sftp;
namespace UnscRelay.Core;
public sealed record PublicKeyInstallationPreview(string Path,string PublicKey,string Fingerprint,bool DirectoryExists,bool FileExists,bool AlreadyPresent,string OriginalHash,int OriginalBytes,string DirectoryPermissions,string FilePermissions,int Owner,int Group);
public sealed record PublicKeyInstallationResult(string Path,bool AlreadyPresent,bool DirectoryCreated);
public sealed partial class SshSession
{
 const int MaximumAuthorizedKeysBytes=1024*1024;
 static string InstallationKey(string value){if(value is not{Length:>0 and <=32768})throw new ArgumentException("Chiave pubblica non valida.");var parsed=NativeIdentity.Parse(value);if(parsed.Algorithm is not("ssh-ed25519" or "ssh-rsa" or "ecdsa-sha2-nistp256" or "ecdsa-sha2-nistp384" or "ecdsa-sha2-nistp521"))throw new ArgumentException("Seleziona una chiave SSH software supportata, senza certificato.");return parsed.PublicKey;}
 static bool InstalledKey(byte[] content,string key){var parts=key.Split(' ');foreach(var line in Encoding.UTF8.GetString(content).Split('\n')){if(line.TrimStart().StartsWith('#'))continue;var fields=line.Split((char[]?)null,StringSplitOptions.RemoveEmptyEntries);for(var index=0;index+1<fields.Length;index++)if(fields[index]==parts[0]&&fields[index+1]==parts[1])return true;}return false;}
 static void InstallationPermissions(ISftpFile item,int owner,bool directory){if(item.IsSymbolicLink||item.IsDirectory!=directory||!directory&&!item.IsRegularFile||item.Attributes.UserId!=owner||item.Attributes.GroupCanWrite||item.Attributes.OthersCanWrite)throw new IOException("Proprietario, permessi o collegamenti della configurazione SSH richiedono una verifica manuale.");}
 static (PublicKeyInstallationPreview Preview,byte[] Original) ReadInstallation(SftpClient channel,string publicKey,CancellationToken ct){
  ct.ThrowIfCancellationRequested();var key=InstallationKey(publicKey);var home=channel.Get(channel.WorkingDirectory);if(home.FullName.Length>3900)throw new IOException("Percorso SSH troppo lungo.");InstallationPermissions(home,home.Attributes.UserId,true);var directory=home.FullName.TrimEnd('/')+"/.ssh";var path=directory+"/authorized_keys";BridgeParents(channel,directory);var directoryExists=channel.Exists(directory);if(directoryExists)InstallationPermissions(channel.Get(directory),home.Attributes.UserId,true);var fileExists=directoryExists&&channel.Exists(path);byte[] original=[];string fileMode="-rw-------";int group=home.Attributes.GroupId;
  if(fileExists){var file=channel.Get(path);InstallationPermissions(file,home.Attributes.UserId,false);if(file.Attributes.Size is <0 or >MaximumAuthorizedKeysBytes)throw new IOException("authorized_keys supera il limite di verifica.");using var input=channel.OpenRead(path);using var output=new MemoryStream();var buffer=new byte[16384];try{int read;while((read=input.Read(buffer,0,buffer.Length))>0){ct.ThrowIfCancellationRequested();if(read>MaximumAuthorizedKeysBytes-output.Length)throw new IOException("authorized_keys è cambiato o supera il limite.");output.Write(buffer,0,read);}original=output.ToArray();}finally{CryptographicOperations.ZeroMemory(buffer);}fileMode=FilePresentation.Permissions(file.Attributes);group=file.Attributes.GroupId;}
  var fingerprint=NativeIdentity.Parse(key).Fingerprint;return(new(path,key,fingerprint,directoryExists,fileExists,InstalledKey(original,key),Convert.ToHexString(SHA256.HashData(original)),original.Length,directoryExists?FilePresentation.Permissions(channel.Get(directory).Attributes):"drwx------",fileMode,home.Attributes.UserId,group),original);
 }
 public async Task<PublicKeyInstallationPreview> PreparePublicKeyInstallationAsync(string publicKey,CancellationToken ct=default){using var channel=await FileChannel(ct);using var stop=ct.Register(()=>channel.Dispose());try{return await Task.Run(()=>{var read=ReadInstallation(channel,publicKey,ct);try{return read.Preview;}finally{CryptographicOperations.ZeroMemory(read.Original);}},ct);}catch(Exception)when(ct.IsCancellationRequested){throw new OperationCanceledException(ct);}}
 public async Task<PublicKeyInstallationResult> InstallPublicKeyAsync(PublicKeyInstallationPreview expected,CancellationToken ct=default){
  using var channel=await FileChannel(ct);using var stop=ct.Register(()=>channel.Dispose());try{return await Task.Run(()=>{
   var first=ReadInstallation(channel,expected.PublicKey,ct);byte[]? payload=null;var directoryCreated=false;var partial="";var created=false;var published=false;
   try{if(first.Preview!=expected)throw new IOException("La configurazione SSH è cambiata. Ripeti l’anteprima.");if(expected.AlreadyPresent)return new PublicKeyInstallationResult(expected.Path,true,false);var directory=expected.Path[..expected.Path.LastIndexOf('/')];if(!expected.DirectoryExists){channel.CreateDirectory(directory);directoryCreated=true;channel.ChangePermissions(directory,700);}
    var baseline=ReadInstallation(channel,expected.PublicKey,ct);try{if(baseline.Preview.FileExists!=expected.FileExists||baseline.Preview.OriginalHash!=expected.OriginalHash)throw new IOException("authorized_keys è cambiato: nessuna sostituzione eseguita.");var append=Encoding.ASCII.GetBytes((first.Original.Length>0&&first.Original[^1]!=10?"\n":"")+expected.PublicKey+" unsc-relay\n");if(append.Length>MaximumAuthorizedKeysBytes-first.Original.Length)throw new IOException("authorized_keys supererebbe il limite.");payload=new byte[first.Original.Length+append.Length];first.Original.CopyTo(payload,0);append.CopyTo(payload,first.Original.Length);partial=expected.Path+".relay-install-"+Guid.NewGuid().ToString("N")+".partial";using(var output=channel.Open(partial,FileMode.CreateNew,FileAccess.Write)){created=true;channel.ChangePermissions(partial,600);ct.ThrowIfCancellationRequested();output.Write(payload);output.Flush();}
     using(var stagedContent=channel.OpenRead(partial))if(CheckpointHash(stagedContent,ct,payload.Length)!=Convert.ToHexString(SHA256.HashData(payload)))throw new IOException("Verifica della configurazione SSH non riuscita.");var final=ReadInstallation(channel,expected.PublicKey,ct);try{if(final.Preview!=baseline.Preview)throw new IOException("La configurazione SSH è cambiata durante l’installazione.");}finally{CryptographicOperations.ZeroMemory(final.Original);}ct.ThrowIfCancellationRequested();
     var stagedFile=channel.Get(partial);InstallationPermissions(stagedFile,expected.Owner,false);var staged=stagedFile.Attributes;if(staged.GroupId!=expected.Group)staged.GroupId=expected.Group;
     if(expected.FileExists){var currentFile=channel.Get(expected.Path);InstallationPermissions(currentFile,expected.Owner,false);var permissions=currentFile.Attributes;if(permissions.GroupId!=expected.Group||FilePresentation.Permissions(permissions)!=expected.FilePermissions)throw new IOException("La configurazione SSH è cambiata durante l’installazione.");staged.OwnerCanRead=permissions.OwnerCanRead;staged.OwnerCanWrite=permissions.OwnerCanWrite;staged.OwnerCanExecute=permissions.OwnerCanExecute;staged.GroupCanRead=permissions.GroupCanRead;staged.GroupCanWrite=permissions.GroupCanWrite;staged.GroupCanExecute=permissions.GroupCanExecute;staged.OthersCanRead=permissions.OthersCanRead;staged.OthersCanWrite=permissions.OthersCanWrite;staged.OthersCanExecute=permissions.OthersCanExecute;}channel.SetAttributes(partial,staged);var protectedStage=channel.Get(partial);InstallationPermissions(protectedStage,expected.Owner,false);if(protectedStage.Attributes.GroupId!=expected.Group||FilePresentation.Permissions(protectedStage.Attributes)!=expected.FilePermissions)throw new IOException("Proprietario, permessi o collegamenti della configurazione SSH richiedono una verifica manuale.");channel.RenameFile(partial,expected.Path,expected.FileExists);published=true;return new PublicKeyInstallationResult(expected.Path,false,directoryCreated);
    }finally{CryptographicOperations.ZeroMemory(baseline.Original);}
   }finally{CryptographicOperations.ZeroMemory(first.Original);if(payload!=null)CryptographicOperations.ZeroMemory(payload);if(created&&!published&&channel.IsConnected){try{channel.DeleteFile(partial);}catch(Exception error)when(error is Renci.SshNet.Common.SshException or IOException){/* A public-key-only partial can remain after a failed transport; original access is not removed. */}}}
  },ct);}catch(Exception)when(ct.IsCancellationRequested){throw new OperationCanceledException(ct);}
 }
 public Task VerifyKeyAuthenticationAsync(CancellationToken ct=default){if(_nativeFileChannel!=null||_ssh.IsConnected||Profile.Authentication!="key"||Profile.KeyboardFallback||_ssh.ConnectionInfo.AuthenticationMethods.Count()!=1||_ssh.ConnectionInfo.AuthenticationMethods.Single() is not PrivateKeyAuthenticationMethod)throw new InvalidOperationException("La verifica richiede esclusivamente la chiave selezionata, senza fallback.");return _ssh.ConnectAsync(ct);}
}
